"""Every number in the Answers is generated by the engine and frozen (decision D6).

If this fails, the engine changed an answer number. Inspect the diff, then regenerate with
``python -m labcalc.answers > ../web/src/content/generated/answers.json`` (and the examples file).
"""

import json
from pathlib import Path

from mpmath import mpf

from labcalc import answers, golden

GEN = Path(__file__).resolve().parents[2] / "web" / "src" / "content" / "generated"


def test_answers_snapshot():
    frozen = (GEN / "answers.json").read_text(encoding="utf-8")
    assert answers.dumps() == frozen.replace("\r\n", "\n")


def test_examples_snapshot():
    frozen = json.loads((GEN / "examples.json").read_text(encoding="utf-8"))
    assert golden.examples() == frozen


def test_key_answer_values():
    a = answers.generate()
    q3 = [r["lambda"]["d"] for r in a["exp3"]["q3_table"]]
    assert q3 == ["656.11", "486.01", "433.94", "410.07", "396.91"]
    assert a["exp4"]["q5"]["err_pct"]["d"] == "1.8 %"
    assert a["exp5"]["q2"]["ratio_3_6"]["d"] == "3.650"
    assert a["exp7"]["q5_table"][2]["gamma"]["d"] == "196.70"
    assert abs(mpf(a["exp3"]["eq37_codata"]["v"]) / mpf("10973731.568157") - 1) < mpf("1e-9")
